def policy(obs,P):
    x=obs[0]
    y=obs[1]
    vx=obs[2]
    vy=obs[3]
    angle=obs[4]
    ang_v=obs[5]
    leg_left=obs[6]
    leg_right=obs[7]
    if leg_left>0.5 and leg_right>0.5:
        if abs(angle) < P['a_thr']*1.5 and abs(ang_v) < P['av_thr']*3.0:
            return 0
    if vy < P['vy_thr']:
        if abs(x) < P['x_main_thr'] and y < P['y_main_thr'] and abs(vx) < P['vx_thr']*2.0:
            return 2
        return 0
    if angle < -P['a_thr'] or ang_v < -P['av_thr']:
        return 1
    if angle > P['a_thr'] or ang_v > P['av_thr']:
        return 3
    if x < -P['x_thr'] or vx < -P['vx_thr']:
        return 3
    if x > P['x_thr'] or vx > P['vx_thr']:
        return 1
    if vy < P['vy_thr2'] and abs(x) < P['x_main_thr2']:
        return 2
    return 0
